{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyM56xagfaRPDzJp4hVjdaWG"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":6,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"4s5gVnlQ4tbp","executionInfo":{"status":"ok","timestamp":1794390532059,"user_tz":-420,"elapsed":14878,"user":{"displayName":"Hisyam Fithroturrohim","userId":"09005319930458663373"}},"outputId":"a8258727-2c9e-4dcc-ad07-bdf640038c5a"},"outputs":[{"output_type":"stream","name":"stdout","text":["Masukkan sisa waktu: 15\n","Masukkan durasi untuk modul ke -1: 2\n","Masukkan durasi untuk modul ke -2: 3\n","Masukkan durasi untuk modul ke -3: 4\n","Masukkan durasi untuk modul ke -4: 5\n","1. Belajar\n","2. Tidur\n","Pilih tindakan (1/2): 1\n","Pilih modul yang ingin dipelajari (1-4): 2\n","Masukkan durasi belajar : 4\n","1. Belajar\n","2. Tidur\n","Pilih tindakan (1/2): 2\n","Prediksi nilai UAS yang akan didapatkan oleh Tuan Ky adalah 25.0.\n"]}],"source":["\n","# Nama/NIM  : Hisyam Fithroturrrohim 15626049\n","# Tanggal   : 11 November 2026\n","# Deskripsi : Praktikum Berpikir Komputasional Modul 4 (Prediksi hasil UAS)\n","\n","def belajar(waktu, energi, durasi):\n","\n","    if durasi > waktu:\n","        durasi = waktu\n","\n","    durasi_energi = energi / 5\n","\n","    if durasi > durasi_energi:\n","        durasi = durasi_energi\n","\n","    waktu = waktu - durasi\n","    energi = energi - (durasi * 5)\n","\n","    return waktu, energi, durasi\n","\n","def tidur(waktu, energi):\n","    energi = energi + (waktu * 12.5)\n","\n","    if energi > 100:\n","        energi = 100\n","\n","    waktu = 0\n","\n","    return waktu, energi\n","\n","def prediksi_nilai(T, t, energi):\n","    total = 0\n","\n","    for i in range(4):\n","        if T[i] > t[i]:\n","            total = total + 1\n","        else:\n","            total = total + (T[i] / t[i])\n","\n","    rata_rata = total / 4\n","    faktor_energi = (100**2 - (100 - energi)**2) / 100\n","    nilai = rata_rata * faktor_energi\n","\n","    return nilai\n","\n","\n","waktu = float(input(\"Masukkan sisa waktu: \"))\n","\n","energi = 100\n","\n","t = []\n","\n","for i in range(4):\n","    durasi = float(input(\"Masukkan durasi untuk modul ke -\" + str(i + 1) + \": \"))\n","    t.append(durasi)\n","\n","T = [0, 0, 0, 0]\n","\n","selesai = False\n","\n","while not selesai:\n","\n","    if waktu <= 0:\n","        waktu, energi = tidur(waktu, energi)\n","        selesai = True\n","\n","    elif energi <= 0:\n","        print(\"Tuan Ky terpaksa tidur karena kehabisan energi !\")\n","        waktu, energi = tidur(waktu, energi)\n","        selesai = True\n","\n","    else:\n","        print(\"1. Belajar\")\n","        print(\"2. Tidur\")\n","\n","        pilihan = int(input(\"Pilih tindakan (1/2): \"))\n","\n","        while pilihan != 1 and pilihan != 2:\n","            print(\"Pilihan tidak tersedia !\")\n","            pilihan = int(input(\"Pilih tindakan (1/2): \"))\n","\n","        if pilihan == 1:\n","\n","            modul = int(input(\"Pilih modul yang ingin dipelajari (1-4): \"))\n","\n","            while modul < 1 or modul > 4:\n","                print(\"Modul tidak tersedia !\")\n","                modul = int(input(\"Pilih modul yang ingin dipelajari (1-4): \"))\n","\n","            durasi = float(input(\"Masukkan durasi belajar : \"))\n","\n","            waktu, energi, realita = belajar(waktu, energi, durasi)\n","\n","            T[modul - 1] = T[modul - 1] + realita\n","\n","        elif pilihan == 2:\n","            waktu, energi = tidur(waktu, energi)\n","            selesai = True\n","\n","nilai = prediksi_nilai(T, t, energi)\n","\n","print(\"Prediksi nilai UAS yang akan didapatkan oleh Tuan Ky adalah\", str(nilai) + \".\")"]}]}